// Stop only the exact owned QA process; no normal preview process is targeted.
import fs from 'node:fs';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {json} from './seal-simple-website-successor.mjs';
const dir='F:/VisibleMedicine/staging/20261024-tour-explore-website/browser',started=json(dir+'/STARTED.json');assert.equal(started.pid,135204);const shell='C:/Windows/System32/WindowsPowerShell/v1.0/powershell.exe';
const command=String.raw`$p = Get-CimInstance Win32_Process -Filter 'ProcessId=135204'; if ($null -eq $p -or $p.Name -ne 'node.exe' -or $p.CommandLine -ne '"C:\Program Files\nodejs\node.exe" serve-tour-explore-website-20261024.mjs') { throw 'Owned QA process identity changed' }; $identity = $p | Select-Object ProcessId,ParentProcessId,Name,CommandLine,CreationDate; Stop-Process -Id 135204 -ErrorAction Stop; $left = @(Get-CimInstance Win32_Process -Filter 'ProcessId=135204'); if ($left.Count -ne 0) { throw 'QA process remains' }; $identity | ConvertTo-Json -Compress`;
const identity=JSON.parse(execFileSync(shell,['-NoProfile','-NonInteractive','-Command',command],{encoding:'utf8',windowsHide:true}));assert.equal(identity.ProcessId,started.pid);const receipt={at:new Date().toISOString(),pid:started.pid,code:null,verifiedStopped:true,method:'Identity-checked Stop-Process of owned QA server only',reason:'Non-TTY session stdin was closed; q cleanup could not be submitted.',identity,inMemoryRequestLogPersisted:false,previewChanged:false};fs.writeFileSync(dir+'/TERMINAL.json',JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});
const p=json('CURRENT_CHECKPOINT.json');assert.equal(p.activeWork.current.ownerPreviewPolicy.restartPermitted,false);p.activeWork.current.activeExecutionSessions=p.activeWork.current.activeExecutionSessions.filter(r=>r.role!=='tour-explore-website-browser');const text=JSON.stringify(p,null,2)+'\n';assert(Buffer.byteLength(text)<65536);fs.writeFileSync('CURRENT_CHECKPOINT.json',text);console.log(JSON.stringify(receipt));
